import { TextureLoader, DataTexture, SRGBColorSpace, ClampToEdgeWrapping } from 'three';
// Authored albedo / tangent-space normal + roughness. Original sculpt/UVs unmodified.
const albedoURI = 'data:image/png;base64,';
const detailURI = 'data:image/png;base64,';
export function installSkinStudy(material, { enabled = false, strength = 1, onLoad = () => {}, texture = null } = {}) {
  if (!material?.isMeshStandardMaterial) throw new TypeError('Skin study requires MeshStandardMaterial.');
  const previousCompile = material.onBeforeCompile, previousKey = material.customProgramCacheKey;
  const amount = { value: enabled ? Math.max(0, Math.min(1, strength)) : 0 };
  let lastStrength = Math.max(0, Math.min(1, strength)), disposed = false;
  const owned = [];
  const pending = [];
  function load(uri, fallback, srgb=false) {
    let tex;
    if (typeof document === 'undefined') { tex = new DataTexture(new Uint8Array(fallback),1,1); tex.needsUpdate=true; }
    else pending.push(new Promise((resolve,reject)=>{tex=new TextureLoader().load(uri,resolve,undefined,reject);}));
    if(srgb) tex.colorSpace=SRGBColorSpace;
    tex.wrapS=tex.wrapT=ClampToEdgeWrapping;owned.push(tex);return tex;
  }
  const faceDetail = texture || load(albedoURI,[66,43,32,255],true);
  faceDetail.colorSpace=SRGBColorSpace;faceDetail.wrapS=faceDetail.wrapT=ClampToEdgeWrapping;
  const surfaceDetail=load(detailURI,[128,128,255,168]);
  const ready=Promise.all(pending).then(()=>{if(!disposed)onLoad();});
  material.onBeforeCompile = function(shader,renderer) {
    previousCompile.call(this,shader,renderer);
    if(!shader.fragmentShader.includes('varying float vHairAmount;') || !shader.fragmentShader.includes('varying vec3 vNativePosition;')) throw new Error('Install the native haircut material patch before the skin study.');
    shader.uniforms.uSkinStudy=amount;shader.uniforms.uFaceDetail={value:faceDetail};shader.uniforms.uSkinSurface={value:surfaceDetail};
    shader.fragmentShader=`uniform float uSkinStudy; uniform sampler2D uFaceDetail; uniform sampler2D uSkinSurface;
      mat3 skinFrame(vec3 eye,vec3 N,vec2 uv){
        vec3 q0=dFdx(eye),q1=dFdy(eye);vec2 s0=dFdx(uv),s1=dFdy(uv);
        vec3 p1=cross(q1,N),p0=cross(N,q0);
        vec3 T=p1*s0.x+p0*s1.x,B=p1*s0.y+p0*s1.y;
        float scale=inversesqrt(max(max(dot(T,T),dot(B,B)),1e-16));return mat3(T*scale,B*scale,N);
      }\n`+shader.fragmentShader;
    shader.fragmentShader=shader.fragmentShader.replace('#include <alphamap_fragment>',`
      float skinStudyMask = (1.0 - vHairAmount) * uSkinStudy;
      vec2 faceUV=vec2(vNativePosition.x/0.5777777778+0.5,(vNativePosition.y-0.08)/0.65+0.5);
      vec4 faceDetailSample=texture2D(uFaceDetail,faceUV);
      vec4 surfaceSample=texture2D(uSkinSurface,faceUV);
      float frontSurface=smoothstep(0.17,0.23,vNativePosition.z);
      float sourceLuma=dot(diffuseColor.rgb,vec3(0.2126,0.7152,0.0722));
      float sourceDetail=mix(1.0,clamp(sourceLuma/0.0037,0.36,1.8),0.36);
      vec3 skinColor=mix(vec3(0.0545,0.0242,0.0144),faceDetailSample.rgb,frontSurface);
      // Preserve atlas beard / nasolabial microcontrast rather than bleaching it away.
      skinColor*=sourceDetail;
      diffuseColor.rgb=mix(diffuseColor.rgb,skinColor,skinStudyMask);
      #include <alphamap_fragment>
    `);
    shader.fragmentShader=shader.fragmentShader.replace('#include <metalnessmap_fragment>',`
      roughnessFactor=mix(roughnessFactor,mix(0.67,surfaceSample.a,frontSurface),skinStudyMask);
      #include <metalnessmap_fragment>
    `);
    shader.fragmentShader=shader.fragmentShader.replace('#include <normal_fragment_maps>',`
      #include <normal_fragment_maps>
      // Real light-reactive relief. Side projection keeps pores from stretching at temples.
      vec2 sideUV=vec2(vNativePosition.z/0.65+0.28,(vNativePosition.y-0.08)/0.65+0.5);
      vec3 sideN=texture2D(uSkinSurface,sideUV*0.22).xyz*2.0-1.0;
      vec3 frontN=surfaceSample.xyz*2.0-1.0;
      frontN.xy*=0.8;sideN.xy*=0.65;
      vec3 frontNormal=normalize(skinFrame(-vViewPosition,normal,faceUV)*frontN);
      vec3 sideNormal=normalize(skinFrame(-vViewPosition,normal,sideUV)*sideN);
      normal=normalize(mix(normal,normalize(mix(sideNormal,frontNormal,frontSurface)),skinStudyMask));
    `);
    shader.fragmentShader=shader.fragmentShader.replace('#include <lights_physical_fragment>',`
      #include <lights_physical_fragment>
      material.specularColor=mix(material.specularColor,vec3(0.028),skinStudyMask);
      material.specularColorBlended=mix(material.specularColor,diffuseColor.rgb,metalnessFactor);
    `);
  };
  material.customProgramCacheKey=function(){return previousKey.call(this)+'|fitted-face-material-v7';};material.needsUpdate=true;
  return { ready,
    setEnabled(value){if(!disposed)amount.value=value?lastStrength:0;},
    setStrength(value){lastStrength=Math.max(0,Math.min(1,value));if(!disposed&&amount.value>0)amount.value=lastStrength;},
    get enabled(){return amount.value>0;},
    dispose(){if(disposed)return;disposed=true;owned.forEach(t=>t.dispose());material.onBeforeCompile=previousCompile;material.customProgramCacheKey=previousKey;material.needsUpdate=true;}
  };
}
